solution:
const json = '{"num": 42, "str": "hello", "bool": true, "nullVal": null, "arr": [1,2,3]}'
const parsed = JSON.parse(json)
return {
  numType: typeof parsed.num,
  strType: typeof parsed.str,
  boolType: typeof parsed.bool,
  nullType: typeof parsed.nullVal,
  arrType: Array.isArray(parsed.arr)
}
